/* DIHASILKAN oleh tools/build-tutorial.mjs — jangan edit manual */
window.JASMIN_TUTOR = [{"id":"01","title":"Menilai Keadaan Darurat, Membunyikan Alarm, dan Melapor dengan Format LAPOR","steps":[{"n":1,"do":"Menilai apakah kejadian termasuk darurat memakai aturan 3 pertanyaan (ada yang berpotensi cedera, bisa membesar dalam 10 menit, perlu orang atau alat dari luar area)","items":[{"k":"wajib","t":"**Satu saja jawaban \"ya\" pada 3 pertanyaan berarti bunyikan darurat**; bila ragu, perlakukan sebagai darurat karena menurunkan status jauh lebih mudah daripada mengejar waktu yang hilang."},{"k":"lakukan","t":"Contoh batas: oli menetes 1-2 liter yang sudah ditahan spill kit bukan darurat; oli keluar dari bund atau masuk drainase adalah darurat."},{"k":"apd","t":"APD sesuai pekerjaan tetap dipakai."}]},{"n":2,"do":"Menyelamatkan diri lebih dulu: menjauh minimal 15 meter dari sumber bahaya, melawan arah angin dan ke tempat lebih tinggi bila ada asap atau tumpahan","items":[{"k":"wajib","t":"**Amankan diri dulu, jangan mendekat untuk melihat atau merekam**; hentikan mesin atau sumber energi hanya bila aman dan dalam jangkauan satu detik."},{"k":"lakukan","t":"Beri peringatan lisan kepada rekan terdekat saat menjauh."},{"k":"apd","t":"Helm dan sepatu keselamatan tetap dipakai."}]},{"n":3,"do":"Membunyikan alarm atau berteriak \"DARURAT\" dan menelepon ekstensi/nomor darurat lokasi sambil menyebut kode darurat dan lokasi","items":[{"k":"wajib","t":"**Bunyikan alarm dan telepon, jangan tunggu memastikan sendiri dan jangan menunggu atasan**; menelepon lebih dulu tidak pernah salah."},{"k":"lakukan","t":"Sebut kode lalu lokasi dua kali, pelan dan jelas, mis. \"Kode Merah, workshop bay 3, Kode Merah, workshop bay 3\"."},{"k":"lakukan","t":"Alarm diuji terdengar sampai area bising."}]},{"n":4,"do":"Melapor 20 detik dengan format LAPOR: Lokasi, Apa yang terjadi, Personel (jumlah dan kondisi korban), Objek dan bahaya lain, Reaksi dan permintaan bantuan","items":[{"k":"wajib","t":"**Pakai lima baris LAPOR secara berurutan**; sebut patokan yang bisa dilihat dari jalan atau koordinat; sebut nama dan nomor telepon pelapor; **jangan menutup telepon sebelum operator menutup**."},{"k":"lakukan","t":"Tempatkan satu orang di gerbang untuk memandu kendaraan darurat sampai titik kejadian; nomor nasional: 112 (terpadu), 113 (damkar), 110 (polisi), 118/119 (ambulans), 115 (SAR)."}]},{"n":5,"do":"Menetapkan level kejadian (Level 1 lokal, Level 2 cabang/lokasi, Level 3 nasional) dan memberi tahu atasan sesuai batas waktu","items":[{"k":"wajib","t":"**Level hanya boleh naik cepat dan turun pelan**; siapa pun boleh menaikkan level, hanya Chief of Emergency yang boleh menurunkan setelah kondisi terkendali dan orang terhitung."},{"k":"lakukan","t":"Level 3 (fatality, korban banyak, kebakaran besar, bencana, potensi menjadi berita): telepon pimpinan dalam 15 menit. Level 2 (korban rawat, kerusakan properti, tumpahan keluar area): telepon dalam 1 jam dan kirim laporan awal tertulis dalam 24 jam. Level 1: laporan awal dalam 1x24 jam."}]}],"aturan":["Amankan diri dulu, alarm, telepon, baru tindakan lain.","Ragu berarti darurat.","Menelepon bantuan tidak memerlukan izin siapa pun."],"siap":["Nomor darurat lokasi terpasang, diuji telepon tiap tiga bulan, dan terisi pada kartu kontak darurat.","Satu orang ditugaskan memandu kendaraan darurat di gerbang.","Level kejadian ditetapkan dan dicatat jamnya.","Laporan awal tertulis dikirim sesuai batas waktu level."],"jangan":["Melapor ke atasan lewat chat lalu menunggu dibalas — hindari dengan menelepon nomor darurat lokasi lebih dulu.","Menyebut penyebab (\"karena kelalaian operator\") pada laporan awal — hindari; penyebab adalah hasil investigasi."],"tips":["Enam kode darurat yang lazim: Merah (kebakaran, ledakan), Hitam (bencana alam), Putih (insiden fatal, cedera berat, keracunan), Oranye (tumpahan B3), Kuning (kerusuhan, blokade), Biru (ancaman bom). Samakan dengan kode yang berlaku di lokasi; jangan menambah kode baru antar lokasi.","Kode Putih bukan untuk luka ringan yang bisa berjalan sendiri ke klinik.","Kode Hitam untuk gempa dimulai setelah guncangan berhenti, bukan saat terasa."],"perhatian":["Panik membuat orang bercerita panjang; format LAPOR menjaga laporan tetap 20 detik.","Waktu sering terbuang di dalam kawasan sendiri karena tidak ada yang memandu kendaraan darurat di gerbang.","Mengirim kabar ke grup chat tidak sama dengan melapor."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, sesuai pekerjaan saat kejadian.","tambahan":"Rompi reflektif untuk personel yang memandu di gerbang atau jalan."},"darurat":{"potensi":"Bantuan terlambat karena laporan tidak jelas, salah lokasi, atau tidak ada yang memandu.","respon":"Ulangi laporan dengan format LAPOR, telepon nomor darurat publik (112) bila tim internal tidak ada, dan kirim orang ke gerbang.","alat":"Telepon/radio yang berfungsi, daftar nomor darurat, alarm, rompi reflektif."},"catatan":"Kunci keberhasilan seluruh modul tanggap darurat adalah tiga hal: tahu harus berbuat apa dalam 60 detik pertama, berani membunyikan alarm walau ternyata salah, dan tahu siapa yang memimpin saat itu juga.","dasar":["UU No. 1/1970","PP No. 50/2012 (SMK3 - kesiapan tanggap darurat)","praktik industri","PP No. 50/2012","Kepmenaker No. 186/1999 (unit penanggulangan kebakaran - sistem alarm)","Pedoman nomor layanan darurat (perlu verifikasi nomor setempat)","Permenaker No. PER.03/MEN/1998 (pelaporan kecelakaan)"]},{"id":"02","title":"Kebakaran Bangunan (Kantor, Workshop, Gudang)","steps":[{"n":1,"do":"Menekan tombol alarm terdekat, berteriak \"KEBAKARAN\", dan menelepon nomor darurat dengan Kode Merah serta lokasi","items":[{"k":"wajib","t":"**Tekan alarm dan telepon lebih dulu, baru lakukan tindakan lain**; sebut: Kode Merah, lokasi, apa yang terbakar."},{"k":"lakukan","t":"Teriak \"KEBAKARAN\" tiga kali ke arah rekan."}]},{"n":2,"do":"Memadamkan api hanya bila masih sebatas badan dan terlatih dengan APAR (Tarik pin, Arahkan ke pangkal api, Semprot, Sapu), berpasangan","items":[{"k":"wajib","t":"**Hentikan pemadaman bila api lebih tinggi dari badan, mengeluarkan asap hitam tebal, atau dua APAR belum memadamkan; mundur, tutup pintu, tunggu damkar**; berdiri membelakangi jalan keluar, jarak 2-3 meter, angin dari belakang."},{"k":"lakukan","t":"Kelas B (oli, solar, grease): powder, foam, CO₂, bukan air. Kelas C (listrik hidup): CO₂ atau powder, bukan air atau foam. Satu orang memadamkan, satu mengawasi jalan keluar dan rekan."},{"k":"lingkungan","t":"Air limpasan pemadaman yang bercampur oli ditampung, tidak masuk drainase."},{"k":"apd","t":"Sarung tangan, masker bila berasap."}]},{"n":3,"do":"Memutus listrik area itu dari panel dan menutup katup gas serta bahan bakar terdekat bila aman dijangkau","items":[{"k":"wajib","t":"**Matikan listrik dari panel, bukan saklar ruangan**; jangan mendekati panel yang sudah berasap atau terbakar."},{"k":"lakukan","t":"Building maintenance mematikan listrik, gas, dan kompresor, menyalakan pompa hidran dan genset, dan menurunkan lift ke lantai dasar."},{"k":"apd","t":"Sarung tangan isolasi bila menyentuh panel."}]},{"n":4,"do":"Mengevakuasi lewat jalur evakuasi menunduk bila berasap, menutup pintu (tidak mengunci) di belakang, tanpa memakai lift, menuju titik kumpul","items":[{"k":"wajib","t":"**Jangan membuka pintu yang gagangnya panas dan jangan berdiri tegak di ruangan berasap; asap membunuh lebih dulu daripada api**; bila terjebak, beri tanda dari jendela."},{"k":"lakukan","t":"Warden menyisir ruang rapat, toilet, musala, gudang, ruang panel, tandai pintu yang sudah disisir; bantu tamu, ibu hamil, dan orang yang kesulitan bergerak; jalan cepat, tidak berlari."},{"k":"apd","t":"Kain basah menutup hidung dan mulut bila tidak ada masker."}]},{"n":5,"do":"Menghitung orang di titik kumpul dengan daftar hadir, melapor ke Chief of Emergency, dan menyambut damkar di gerbang","items":[{"k":"wajib","t":"**Hitung dengan daftar hadir, bukan hafalan; jangan masuk kembali untuk mencari orang hilang, laporkan ke Chief of Emergency**; pencarian dilakukan tim berperlengkapan."},{"k":"lakukan","t":"Laporan warden: area, jumlah seharusnya, hadir, nama yang belum hadir, lokasi terakhir terlihat. Security membuka pagar dan memandu damkar, larang siapa pun masuk kembali."},{"k":"apd","t":"Rompi warden agar mudah dikenali."}]},{"n":6,"do":"Menyatakan kejadian selesai: api padam dan dicek ulang 30 menit kemudian, jumlah orang lengkap, listrik dinyalakan setelah diperiksa, Chief of Emergency mengumumkan \"Aman\"","items":[{"k":"wajib","t":"**Pengumuman \"Aman\" hanya dari Chief of Emergency, bukan dari grup chat**; pantau titik api minimal 30 menit."},{"k":"lingkungan","t":"Puing dan bahan pemadam terkontaminasi dikelola sebagai limbah sesuai karakteristiknya."},{"k":"lakukan","t":"Lanjut ke Tutorial 20 untuk pengamanan TKP dan pelaporan."},{"k":"apd","t":"Helm, sepatu, masker saat memeriksa puing."}]}],"aturan":["Alarm dan telepon dulu, padamkan hanya api sebatas badan.","Asap lebih berbahaya daripada api: menunduk dan keluar.","Jangan kembali sebelum \"Aman\"."],"siap":["Jalur evakuasi dan pintu darurat bebas hambatan dan bisa dibuka dari dalam tanpa kunci.","APAR sesuai kelas, tekanan di zona hijau, dan tidak terhalang.","Daftar hadir untuk penghitungan di titik kumpul selalu tersedia, termasuk tamu dan kontraktor.","Pompa hidran dan genset diuji berjalan."],"jangan":["Mengambil laptop, tas, atau kendaraan saat evakuasi — hindari dengan aturan tinggalkan barang.","Memakai lift saat kebakaran — hindari dengan menurunkan lift ke lantai dasar dan memakai tangga."],"tips":["Larangan mutlak: tidak kembali ke gedung sebelum pengumuman aman, tidak memadamkan api yang sudah lebih tinggi dari badan, tidak menyebar foto atau kabar ke media sosial.","Peran regu: Area 1 menangani titik api, Area 2 menyiapkan hidran dan melindungi bahan mudah terbakar di sekitar; hidran dioperasikan minimal tiga orang, air dibuka setelah nozzle siap dipegang.","Pintu ruangan yang berasap dari celah bawah jangan dibuka."],"perhatian":["APAR 3-6 kg habis dalam 8-15 detik sehingga hanya ada satu kesempatan; dekati pada jarak yang tepat dulu, baru semprot.","Pemadam yang terus memadamkan sampai kehabisan jalan keluar adalah penyebab korban terperangkap.","Warden yang masuk kembali sendirian menambah korban."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, sarung tangan kerja.","tambahan":"Masker/respirator saat memeriksa puing, rompi warden, sarung tangan tahan panas bagi regu pemadam."},"darurat":{"potensi":"Kebakaran menjalar ke unit, rak, atau panel, asap memenuhi ruangan, ada bahan mudah meledak dalam radius 10 meter, orang belum keluar.","respon":"Minta bantuan damkar bila dua APAR belum memadamkan atau api menjalar; evakuasi, hitung orang, laporkan yang belum hadir beserta lokasi terakhirnya.","alat":"APAR sesuai kelas, hidran dan selang, alarm, lampu darurat, tandu dan kotak P3K, daftar hadir, radio/telepon."},"catatan":"Kartu aksi ini dipakai untuk 60 detik pertama; pembagian peran lengkap (Chief of Emergency, warden, regu pemadam, first aider, security, maintenance) ada pada Tutorial 18.","dasar":["UU No. 1/1970","Kepmenaker No. 186/1999","PP No. 50/2012","Permenaker No. 4/1980 (APAR)","PP No. 22/2021","Permenaker No. 12/2015 (keselamatan listrik)","Permen LHK P.6/2021 (limbah B3)"]},{"id":"03","title":"Kebakaran Unit Alat Berat atau Kendaraan","steps":[{"n":1,"do":"Menurunkan attachment ke tanah, mematikan engine, dan mengaktifkan battery disconnect atau master switch bila terjangkau tanpa masuk ke area api","items":[{"k":"wajib","t":"**Turunkan attachment, matikan engine, putus sumber listrik hanya bila dapat dijangkau tanpa melewati api**; bila tidak, langsung turun."},{"k":"lakukan","t":"Di site pelanggan, panggil kanal darurat pelanggan lebih dulu karena mereka punya unit damkar yang lebih cepat."},{"k":"apd","t":"Sarung tangan tahan panas, helm."}]},{"n":2,"do":"Operator atau teknisi turun menghadap unit dengan tiga titik tumpu, lalu menjauh minimal 30 meter searah angin datang","items":[{"k":"wajib","t":"**Turun menghadap unit dengan tiga titik tumpu; jangan melompat**; menjauh minimal 30 meter dan searah angin datang."},{"k":"lakukan","t":"Teriakkan Kode Merah dan hitung orang di sekitar unit."},{"k":"apd","t":"Helm, sepatu keselamatan."}]},{"n":3,"do":"Memadamkan dengan APAR ke pangkal api dari bawah atau samping tanpa membuka penuh engine hood, memakai kelas media yang benar","items":[{"k":"wajib","t":"**Jangan membuka penuh engine hood dan jangan naik ke atas unit**; oli, solar, grease adalah kelas B (powder, foam, CO₂ bukan air); panel listrik dan alternator hidup kelas C."},{"k":"lakukan","t":"Berpasangan; mundur bila api mencapai tangki bahan bakar, ban, atau akumulator."},{"k":"apd","t":"Pelindung wajah dan sarung tangan tahan panas."}]},{"n":4,"do":"Menjauhkan unit lain yang bisa dipindahkan dan mengosongkan area 50 meter bila api mencapai ban besar, akumulator, atau tangki","items":[{"k":"wajib","t":"**Jaga jarak minimal 50 meter dari ban OTR yang terbakar atau baru terpanggang; dekati hanya dari arah sisi dinding ban, bukan sisi tapak**."},{"k":"lakukan","t":"Pasang barikade dan jaga area sampai ban dingin; dinginkan unit sekitar dengan air dari jarak aman."},{"k":"lingkungan","t":"Bendung tumpahan bahan bakar, ikuti Tutorial 05."},{"k":"apd","t":"Tidak memasuki zona bahaya tanpa izin Chief of Emergency."}]},{"n":5,"do":"Melapor dan meminta bantuan luar bila api mencapai tangki atau ban, unit dekat bangunan, atau api tidak padam; mengamankan unit dan bukti","items":[{"k":"lakukan","t":"Foto kondisi asli dari beberapa sisi, jangan bersihkan dan jangan memindahkan komponen sebelum diizinkan; lapor dengan format LAPOR; lanjut Tutorial 20."},{"k":"lingkungan","t":"Limbah oli, puing, dan bahan pemadam dikelola sesuai karakteristik."},{"k":"apd","t":"Helm, sepatu, sarung tangan saat memeriksa."}]}],"aturan":["Turun dan menjauh dulu, memadamkan belakangan.","Jarak 50 meter dari ban dan tangki yang terbakar.","Kosongkan area sebelum api mencapai ban."],"siap":["Battery disconnect atau master switch dapat dijangkau dari luar kabin.","APAR kelas B/C terpasang di unit dan kendaraan servis.","Kontak darurat site pelanggan tercatat sebelum bekerja."],"jangan":["Mendekati ban yang terbakar dari sisi tapak — hindari, dekati dari sisi dinding ban dan hanya bila diperlukan.","Menyiram air ke api oli — hindari dengan memakai powder, foam, atau CO₂."],"tips":["Untuk pengelasan atau penggerindaan di bengkel, siapkan APAR dan pengawas api (fire watch) sebelum mulai kerja panas.","Periksa ruang baterai, hose hidrolik yang menyentuh permukaan panas, dan timbunan oli di ruang mesin pada pemeriksaan harian."],"perhatian":["Ban OTR dapat meledak lama setelah api tampak padam.","Hood yang dibuka penuh menyuplai oksigen dan membuat api membesar.","Api oli bertekanan yang disiram air menyebar."],"apd":{"wajib":"Safety helmet, safety glasses, safety shoes toe cap, coverall, sarung tangan kerja.","tambahan":"Pelindung wajah dan sarung tangan tahan panas bagi regu pemadam."},"darurat":{"potensi":"Ledakan ban OTR, ledakan akumulator atau tangki, api menjalar ke unit lain atau bangunan.","respon":"Kosongkan area 50 meter, panggil damkar atau kanal darurat pelanggan, dinginkan unit sekitar dari jarak aman.","alat":"APAR kelas B/C, spill kit, barikade, radio/telepon darurat, kotak P3K."},"catatan":"Api di unit yang sedang dioperasikan di site pelanggan: sistem damkar pelanggan lebih cepat, panggil mereka lebih dulu lalu lapor ke atasan.","dasar":["UU No. 1/1970","Kepmenaker No. 186/1999","OEM Manual (battery disconnect/master switch)","praktik industri","Permenaker No. 4/1980","Praktik industri (OEM ban OTR - perlu verifikasi jarak sesuai manual unit)","PP No. 22/2021","Permenaker No. PER.03/MEN/1998","Permen LHK P.6/2021"]},{"id":"04","title":"Ledakan dan Potensi Ledakan (Tabung Gas, Akumulator, Ban dan Rim, Sistem Bertekanan)","steps":[{"n":1,"do":"Merunduk, melindungi kepala, dan menunggu material berhenti berjatuhan sebelum bergerak setelah terdengar ledakan","items":[{"k":"wajib","t":"**Lindungi kepala dan leher, tunggu material berhenti jatuh**; jangan berdiri tegak atau berlari."},{"k":"apd","t":"Helm dan kacamata tetap terpasang."}]},{"n":2,"do":"Menjauh minimal 100 meter, tidak mendekat untuk melihat, membunyikan Kode Merah, dan menelepon damkar dan ambulans walau belum terlihat korban","items":[{"k":"wajib","t":"**Menjauh 100 meter dan jangan mendekat; telepon damkar dan ambulans lebih dulu**."},{"k":"lakukan","t":"Hitung orang yang tadi bekerja di area itu; tempatkan orang di gerbang."},{"k":"apd","t":"Tidak memasuki area tanpa izin Chief of Emergency."}]},{"n":3,"do":"Mengisolasi listrik, gas, dan bahan bakar ke area itu dari titik yang jauh dan jangan menyalakan atau mematikan saklar di area berbau gas","items":[{"k":"wajib","t":"**Jangan menyalakan atau mematikan saklar di area yang tercium bau gas; putus dari panel yang jauh dan aman**; hentikan kendaraan dan mesin di sekitar."},{"k":"lakukan","t":"Larang api terbuka, merokok, dan telepon genggam dekat area."},{"k":"apd","t":"Tidak memasuki zona gas tanpa alat ukur dan APD yang sesuai."}]},{"n":4,"do":"Mengamankan TKP: tidak menyentuh atau memindahkan pecahan dan sisa material karena menjadi bukti penyebab","items":[{"k":"lakukan","t":"Pasang barikade, foto kondisi asli dari jauh, catat nama dan jam, lanjut Tutorial 20."}]},{"n":5,"do":"Mencegah sebab umum: tidak berdiri sejajar sumbu ban/rim saat mengisi angin, memakai clip-on chuck dengan selang panjang dan safety cage, serta kerja panas dilarang dekat tangki bekas bahan bakar","items":[{"k":"wajib","t":"**Berdiri di sisi tapak ban, pakai safety cage dan clip-on chuck; tangki bekas BBM wajib dibersihkan dan diuji gas sebelum kerja panas; akumulator dibuang tekanannya sesuai manual sebelum dilepas**."},{"k":"lakukan","t":"Masukkan tiga hal ini ke izin kerja panas dan JSEA, bukan hanya poster."},{"k":"apd","t":"Pelindung wajah, helm, sepatu keselamatan."}]}],"aturan":["Menjauh 100 meter, jangan mendekat.","Tidak ada saklar dan api di area berbau gas.","Berdiri di sisi tapak saat mengisi ban."],"siap":["Safety cage dan clip-on chuck tersedia di area ban.","Izin kerja panas memuat uji gas dan pembersihan tangki.","Prosedur pelepasan tekanan akumulator ada pada JSEA dan dipatuhi."],"jangan":["Mendekat untuk melihat setelah ledakan — hindari dengan menjauh 100 meter.","Menyalakan saklar saat tercium gas — hindari; putus listrik dari titik jauh."],"tips":["Pemicu tersering di bengkel alat berat: pengelasan atau gerinda dekat tangki bekas BBM, pelepasan akumulator bertekanan, dan pengisian ban tanpa cage."],"perhatian":["Ledakan kedua dapat lebih besar daripada yang pertama.","Ukuran luka luar tidak menunjukkan keparahan akibat pecahan."],"apd":{"wajib":"Safety helmet, safety glasses, safety shoes toe cap, sarung tangan kerja.","tambahan":"Pelindung wajah saat mengisi ban atau bekerja pada sistem bertekanan."},"darurat":{"potensi":"Ledakan susulan, kebakaran lanjutan, korban terkena pecahan.","respon":"Menjauh 100 meter, Kode Merah, telepon damkar dan ambulans, hitung orang, isolasi sumber energi dari jauh.","alat":"Radio/telepon, APAR, tandu dan kotak P3K, barikade."},"catatan":"Sebab ledakan di bengkel hampir selalu bisa dicegah dengan izin kerja panas yang benar dan pengisian ban memakai cage. # BAGIAN B — TUMPAHAN, CEDERA, DAN KECELAKAAN (DRT)","dasar":["UU No. 1/1970","praktik industri","Kepmenaker No. 186/1999","Permenaker No. 37/2016 (bejana tekan - perlu verifikasi)","Permenaker No. 12/2015","Permenaker No. PER.03/MEN/1998","Permenaker No. 37/2016","Permenaker No. 38/2016","OEM Manual (ban/rim dan akumulator)"]},{"id":"05","title":"Tumpahan Oli, Bahan Bakar, dan Bahan Kimia (B3)","steps":[{"n":1,"do":"Memperingatkan sekitar, mengosongkan area, dan menjauh melawan arah angin ke tempat lebih tinggi; membunyikan Kode Oranye","items":[{"k":"wajib","t":"**Kosongkan area dan matikan sumber api; jangan menyentuh bahan yang belum dikenali**."},{"k":"lakukan","t":"Naikkan level bila volume lebih dari 200 liter, masuk selokan, sungai, atau tanah di luar pagar, ada uap menyengat, atau ada orang terpapar."},{"k":"apd","t":"Ikuti SDS bahan sebelum mendekat."}]},{"n":2,"do":"Mengenali bahan lewat label dan SDS; bila tidak tahu, perlakukan sebagai berbahaya","items":[{"k":"wajib","t":"**Baca label dan SDS sebelum bertindak dan pilih APD sesuai SDS (sarung tangan kain tidak untuk asam, alkali, atau oli)**."},{"k":"lakukan","t":"Jangan mencampur bahan berbeda saat menyerap atau membersihkan."},{"k":"apd","t":"Sarung tangan kimia sesuai SDS, kacamata/pelindung wajah, apron."}]},{"n":3,"do":"Menghentikan sumber tumpahan bila aman: menutup kran, menegakkan drum, menyumbat kebocoran, mematikan pompa","items":[{"k":"wajib","t":"**Hentikan sumber hanya bila aman dan APD lengkap terpasang**; bila tidak bisa, bendung dulu."},{"k":"lakukan","t":"Gunakan kit sumbat kebocoran dan wadah penampung."},{"k":"apd","t":"Sarung tangan kimia, sepatu karet, pelindung wajah."}]},{"n":4,"do":"Membendung sebelum menyerap: menutup lubang drainase dengan drain cover atau karung pasir, membuat tanggul dari absorben","items":[{"k":"wajib","t":"**Bendung dulu, baru serap; jangan menyiram dengan air dan jangan menyapu ke saluran**."},{"k":"lingkungan","t":"Tutup semua inlet drainase di sekitar; siapkan wadah penampung bila sudah masuk saluran."},{"k":"apd","t":"Sarung tangan kimia, sepatu karet."}]},{"n":5,"do":"Menyerap dari luar ke dalam dengan spill kit dan mengumpulkan ke wadah limbah B3 berlabel","items":[{"k":"wajib","t":"**Kumpulkan absorben bekas ke wadah limbah B3 berlabel dan jangan mencampur dengan sampah biasa**."},{"k":"lingkungan","t":"Catat jenis bahan, perkiraan volume, media terdampak, dan tindakan penanggulangan untuk laporan lingkungan; simpan foto sebelum dan sesudah serta manifest limbah B3."},{"k":"apd","t":"Sarung tangan kimia, kacamata, apron."}]},{"n":6,"do":"Menangani orang yang terpapar: bilas kulit dengan air mengalir 15-20 menit dan lepaskan pakaian terkena, lalu ke klinik membawa SDS","items":[{"k":"wajib","t":"**Bilas kulit 15-20 menit (bahan kimia 20-30 menit); bilas mata 15-20 menit di eyewash dengan kelopak dibuka; semua paparan mata dan pernapasan wajib diperiksa tenaga medis**."},{"k":"lakukan","t":"Bawa SDS bahan ke klinik; jangan menggosok mata atau menetesi obat."},{"k":"lingkungan","t":"Tampung air bilasan bila memungkinkan."},{"k":"apd","t":"Penolong memakai sarung tangan kimia."}]}],"aturan":["Bendung sebelum menyerap.","Jangan sapu atau siram ke saluran.","Limbah bekas serap adalah limbah B3."],"siap":["Spill kit lengkap dan terjangkau di setiap titik risiko.","Drain cover tersedia dan dikenal lokasinya.","SDS bahan tersedia di tempat kerja.","Eyewash dan shower diuji mingguan."],"jangan":["Menyiram tumpahan dengan air — hindari; bendung dan serap.","Memakai sarung tangan kain untuk bahan kimia — hindari dengan sarung tangan sesuai SDS."],"tips":["Spill kit minimum: absorben (bantal, sosis, pad), drain cover, sarung tangan dan kacamata, kantong limbah B3, sekop non-percikan, label. Letakkan dekat TPS B3, area servis, tempat pengisian bahan bakar, dan kendaraan servis; isi ulang hari itu juga.","Tumpahan yang keluar dari area perusahaan menjadi urusan kepatuhan lingkungan: dokumentasikan jenis, volume, media terdampak, dan tindakan."],"perhatian":["Tumpahan kecil yang berubah menjadi pelanggaran lingkungan terjadi karena disiram air dan masuk saluran.","Ketidaksiapan dokumen (foto, manifest limbah) biasanya yang berujung sanksi administratif, bukan tumpahannya sendiri."],"apd":{"wajib":"Safety helmet, safety glasses, safety shoes toe cap, coverall, sarung tangan kimia sesuai SDS.","tambahan":"Pelindung wajah, apron kimia, sepatu karet, respirator sesuai SDS."},"darurat":{"potensi":"Tumpahan keluar bund, masuk drainase atau badan air, uap menyengat, orang terpapar.","respon":"Kosongkan area, hentikan sumber bila aman, bendung, tutup drainase, bilas orang terpapar, lapor Kode Oranye.","alat":"Spill kit, drain cover, eyewash/shower, wadah limbah B3, APD kimia, SDS."},"catatan":"Setelah tumpahan ditangani, siapkan laporan lingkungan dan simpan bukti foto serta manifest limbah B3.","dasar":["PP No. 22/2021","Kepmenaker No. 187/1999 (bahan kimia berbahaya - perlu verifikasi)","SDS bahan","Kepmenaker No. 187/1999","Permen LHK P.6/2021","Permenaker No. 15/2008"]},{"id":"06","title":"Cedera Berat dan Henti Napas atau Henti Jantung (Pertolongan Pertama dan RJP)","steps":[{"n":1,"do":"Menghentikan pekerjaan di sekitar, mematikan mesin, menurunkan beban, memasang ganjal; memastikan lokasi aman untuk penolong","items":[{"k":"wajib","t":"**Pastikan aman untuk Anda dan korban sebelum mendekat; korban listrik, gas, dan tumpahan kimia hanya didekati setelah sumber diisolasi**."},{"k":"lakukan","t":"Tunjuk orang tertentu untuk menelepon (\"Kamu, telepon klinik sekarang\"), bukan perintah ke banyak orang."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":2,"do":"Memanggil bantuan dengan format LAPOR sambil tetap di sisi korban; menyiapkan jalur dan orang di gerbang untuk memandu ambulans","items":[{"k":"wajib","t":"**Panggil ambulans dan first aider lebih dulu dengan LAPOR; buka pintu, singkirkan penghalang, tempatkan orang di gerbang**."},{"k":"lakukan","t":"Di site pelanggan hubungi paramedis atau klinik site lebih dulu."}]},{"n":3,"do":"Memeriksa sadar, napas, dan perdarahan; menekan perdarahan besar langsung dengan kain bersih dan tidak dilepas","items":[{"k":"wajib","t":"**Tekan langsung dan kuat, kain tembus darah ditambah lapisan di atasnya tanpa melepas**; tourniquet hanya bila tersedia dan penolong terlatih, catat jam pemasangan dan jangan dilonggarkan sendiri."},{"k":"lingkungan","t":"Limbah medis (kasa, sarung tangan) dikumpulkan di kantong khusus, tidak dibuang ke sampah biasa."},{"k":"apd","t":"Sarung tangan medis, pelindung mata bila ada percikan."}]},{"n":4,"do":"Memulai RJP bila tidak sadar dan tidak bernapas normal: kompresi di tengah dada sekitar 5-6 cm, 100-120 kali per menit, bergantian tiap 2 menit, memakai AED bila ada","items":[{"k":"wajib","t":"**Mulai RJP dalam 4 menit pertama; jangan berhenti sampai korban bernapas normal, AED memerintahkan berhenti, atau petugas medis mengambil alih**; urutan: aman, sadar, panggil bantuan dan AED, napas, kompresi."},{"k":"lakukan","t":"Tunjuk satu orang mengambil AED; nyalakan AED, tempel pad di dada kering, pastikan tidak ada yang menyentuh saat analisis dan kejut, lanjutkan kompresi segera."},{"k":"apd","t":"Sarung tangan medis, face shield bila ada."}]},{"n":5,"do":"Menangani kasus khusus: tidak memindahkan korban dengan curiga cedera leher atau punggung, tidak mencabut benda menancap, tidak meluruskan patah tulang, mengalirkan air 20 menit untuk luka bakar","items":[{"k":"wajib","t":"**Jangan memindahkan korban kecuali lokasi masih berbahaya; tahan kepala segaris badan; ganjal di sekeliling benda menancap tanpa mencabut; luka bakar dialiri air bersih 20 menit, bukan es atau pasta gigi**."},{"k":"lakukan","t":"Memindahkan korban: minimal 4 orang dengan tandu, satu memimpin aba-aba, papan spinal bila curiga cedera tulang belakang."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":6,"do":"Mencatat jam kejadian, kondisi awal, tindakan, dan jam serah terima; mendampingi sampai serah terima ke ambulans atau klinik","items":[{"k":"lakukan","t":"Serahkan catatan dan sebutkan bahan kimia atau obat yang terlibat; selalu bawa ke fasilitas medis bila hilang kesadaran, cedera kepala atau mata, benda masuk tubuh, luka bakar lebih luas dari telapak tangan korban, jatuh lebih dari 1,8 meter, atau terjepit."}]}],"aturan":["Amankan lokasi dulu, lalu sadar, napas, perdarahan.","Tunjuk orang tertentu untuk telepon dan AED.","Jangan pindahkan korban tanpa alasan."],"siap":["Petugas P3K berlisensi sesuai rasio dan tiap shift.","AED terlihat, teruji, dan lokasinya diketahui.","Kotak P3K, tandu, dan papan spinal tersedia.","Akses ambulans bebas dan ada pemandu di gerbang."],"jangan":["Memberi perintah ke banyak orang sekaligus — hindari dengan menunjuk orang tertentu.","Memplester luka akibat serpihan logam lalu lanjut kerja — hindari; selalu ke fasilitas medis."],"tips":["Triase bila korban lebih dari satu: Merah (nyawa terancam, tangani dulu), Kuning (butuh perawatan tapi belum mengancam), Hijau (luka ringan, bisa berjalan), Hitam (tidak ada napas dan nadi atau tidak tertolong). Mulai dengan perintah \"Yang bisa berjalan, ikut saya ke sini.\"","Korban tidak sadar tetapi bernapas normal: posisi pemulihan, pantau napas, jangan tinggalkan sendiri.","Isi kotak P3K diperiksa bulanan dan setiap pemakaian dicatat."],"perhatian":["Ukuran luka luar bukan ukuran keparahan; serpihan logam bisa masuk tubuh dengan luka kecil dan wajib diperiksa pencitraan di fasilitas medis.","Menyelamatkan nyawa paling sering karena tiga hal: menghentikan perdarahan besar, membuka jalan napas, dan RJP dalam 4 menit pertama."],"apd":{"wajib":"Sarung tangan medis, safety helmet, safety shoes toe cap.","tambahan":"Pelindung mata, face shield RJP, apron."},"darurat":{"potensi":"Henti jantung, perdarahan hebat, cedera kepala atau leher, luka bakar luas, benda menancap.","respon":"Amankan lokasi, panggil ambulans dengan LAPOR, tekan perdarahan, mulai RJP, siapkan jalur ambulans.","alat":"Kotak P3K, AED, tandu/papan spinal, selimut, air bersih, formulir catatan."},"catatan":"Materi ini bukan pengganti pelatihan P3K bersertifikat; fungsinya memastikan siapa pun dapat melakukan hal paling menentukan dalam menit-menit pertama.","dasar":["Permenaker No. 15/2008 (P3K di tempat kerja)","UU No. 1/1970","Permenaker No. 15/2008","praktik industri","Pedoman P3K (perlu verifikasi)","Pedoman RJP AHA/ERC (perlu verifikasi edisi terbaru)","Pedoman P3K","Permenaker No. PER.03/MEN/1998"]},{"id":"07","title":"Terjepit, Tertimpa, dan Unit Bergerak Sendiri (Rollaway)","steps":[{"n":1,"do":"Berteriak memperingatkan dan mengosongkan lintasan gerak unit dengan menyingkir ke samping, bukan lari searah gerakan","items":[{"k":"wajib","t":"**Jangan mencoba menghentikan unit dengan badan atau kendaraan lain; kosongkan lintasan dan menyingkir ke samping**."},{"k":"lakukan","t":"Bunyikan alarm dan hitung orang di sekitar unit."},{"k":"apd","t":"Rompi reflektif, helm."}]},{"n":2,"do":"Mengganjal roda atau track dari arah samping memakai wheel chock atau material besar, hanya bila aman dan kompeten, dari posisi berlindung","items":[{"k":"wajib","t":"**Hanya orang kompeten yang mengganjal, dari samping, tidak dari depan atau belakang roda yang bergerak**; bila tidak aman, biarkan unit dan jauhkan semua orang."},{"k":"lakukan","t":"Wheel chock sesuai ukuran roda tersedia di unit dan kendaraan servis."},{"k":"apd","t":"Helm, sepatu keselamatan, rompi reflektif."}]},{"n":3,"do":"Mengisolasi energi: mematikan engine, master switch off, menurunkan attachment ke tanah, membuang tekanan sisa hidrolik atau pneumatik, memasang LOTO","items":[{"k":"wajib","t":"**Matikan energi dan pasang LOTO; jangan bekerja di bawah attachment yang hanya ditahan sistem hidrolik, pakai penopang mekanis; jangan melepas LOTO milik orang lain**."},{"k":"lakukan","t":"Unit dengan gangguan rem tidak boleh dimatikan mesinnya sampai roda diganjal dan area di belakang unit dikosongkan; turun hanya setelah unit terbukti diam."},{"k":"apd","t":"Helm, sarung tangan, sepatu keselamatan."}]},{"n":4,"do":"Menangani korban terjepit: memanggil bantuan medis dulu dan tidak langsung mengangkat beban penjepit","items":[{"k":"wajib","t":"**Angkat beban hanya bersamaan dengan kesiapan penanganan medis; korban diajak bicara dan dipantau terus**."},{"k":"lakukan","t":"Gunakan alat angkat dan penopang mekanis sesuai JSEA pengangkatan; lanjut Tutorial 06 untuk pertolongan pertama."},{"k":"apd","t":"Sarung tangan, helm."}]},{"n":5,"do":"Mengamankan area 30 meter dan tidak memindahkan apa pun sebelum foto kondisi asli diambil","items":[{"k":"lakukan","t":"Barikade, foto dari berbagai sudut, catat nomor unit dan kondisi rem; lanjut Tutorial 20."}]}],"aturan":["Ganjal dulu, matikan kemudian.","Jangan pernah di bawah beban yang hanya ditahan hidrolik.","LOTO hanya dilepas oleh pemiliknya."],"siap":["Wheel chock tersedia dan dipakai pada setiap penghentian di area miring atau saat perbaikan.","Penopang mekanis tersedia sebelum masuk kolong atau di bawah attachment.","Jalur lintasan unit dikosongkan sebelum dioperasikan atau dipindahkan."],"jangan":["Menahan unit dengan kendaraan lain — hindari.","Melepas LOTO rekan dengan alasan mendesak — hindari tanpa pengecualian."],"tips":["Pada unit dengan peringatan rem parkir error, ganjal dulu, baru matikan mesin, dan turun hanya setelah unit terbukti diam."],"perhatian":["Unit yang dimatikan mesinnya saat kondisi error rem masih aktif dapat bergerak sendiri saat operator hendak turun.","Hidrolik bocor perlahan dapat menurunkan attachment tanpa peringatan."],"apd":{"wajib":"Safety helmet, safety glasses, safety shoes toe cap, coverall, sarung tangan kerja, rompi reflektif.","tambahan":"Sarung tangan anti-potong saat menangani komponen tajam."},"darurat":{"potensi":"Unit meluncur tak terkendali, orang terjepit atau terlindas, attachment jatuh.","respon":"Kosongkan lintasan, ganjal bila aman dan kompeten, isolasi energi, panggil medis untuk korban terjepit.","alat":"Wheel chock, alarm/radio, penopang mekanis, alat angkat, kotak P3K, tandu."},"catatan":"Aturan \"ganjal dulu, matikan kemudian\" lahir dari kejadian nyata unit dengan gangguan rem parkir yang bergerak mundur sendiri setelah mesinnya dimatikan.","dasar":["UU No. 1/1970","Permenaker No. 38/2016","OEM Manual (wheel chock)","praktik industri","OSHA 29 CFR 1910.147","OEM Manual (isolasi energi)","Pedoman P3K","Permenaker No. PER.03/MEN/1998"]},{"id":"08","title":"Kecelakaan Lalu Lintas dan Kendaraan Terguling (Jalan Umum, Jalan Kebun, Jalan Hauling)","steps":[{"n":1,"do":"Mematikan mesin, menarik rem tangan, menyalakan hazard; bila terguling, tidak buru-buru keluar sampai posisi stabil, lalu keluar ke sisi aman","items":[{"k":"wajib","t":"**Matikan mesin dan putus listrik bila dapat dijangkau; keluar ke sisi aman menjauh dari badan jalan, tebing, dan kendaraan lain**."},{"k":"apd","t":"Sabuk pengaman terpasang saat kejadian; helm bila di lokasi kerja."}]},{"n":2,"do":"Memeriksa penumpang satu per satu dengan menyebut nama; yang mengeluh leher atau punggung tidak digerakkan","items":[{"k":"wajib","t":"**Jangan menggerakkan korban dengan keluhan leher atau punggung; tahan kepala segaris badan**; lanjut Tutorial 06."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":3,"do":"Memasang segitiga pengaman sekitar 50 meter di belakang (lebih jauh di tikungan atau berdebu) dan menelepon emergency site atau 112/110 lalu atasan","items":[{"k":"wajib","t":"**Pasang segitiga pengaman dan hazard; pakai rompi reflektif; jarak pandang kurang dari 50 meter berarti berhenti, bukan pelan-pelan**."},{"k":"lakukan","t":"Di area pelanggan, panggil kanal darurat pelanggan lebih dulu; lapor dengan LAPOR; sebut patokan atau koordinat."},{"k":"apd","t":"Rompi reflektif."}]},{"n":4,"do":"Memfoto kondisi asli sebelum kendaraan ditarik (posisi, jejak ban, kerusakan, kondisi jalan) dan mencatat identitas pihak lain serta saksi","items":[{"k":"lakukan","t":"Jangan menarik atau membalikkan kendaraan sebelum semua orang keluar dan foto diambil; jangan meninggalkan lokasi sebelum mencatat; jangan menyelesaikan ganti rugi sendiri tanpa memberi tahu perusahaan."},{"k":"lingkungan","t":"Tumpahan BBM dan oli dibendung dan dikumpulkan, ikuti Tutorial 05."},{"k":"apd","t":"Rompi reflektif."}]},{"n":5,"do":"Menjaga pelaporan jujur: mencatat kronologi apa adanya tanpa menghukum pelapor","items":[{"k":"lakukan","t":"Pastikan pelaporan jujur tidak dihukum agar penyebab sistem bisa diperbaiki; kronologi diambil terpisah dari tiap saksi."}]}],"aturan":["Matikan, aman, cek orang, pasang segitiga, telepon.","Berhenti bila jarak pandang di bawah 50 meter.","Foto sebelum menarik."],"siap":["Segitiga pengaman, APAR, P3K, dan rompi reflektif ada di setiap kendaraan.","Pengemudi terlatih dan terotorisasi.","Rencana perjalanan dan jam check-in diketahui satu orang di kantor."],"jangan":["Menarik kendaraan sebelum difoto — hindari.","Meninggalkan lokasi tanpa mencatat saksi — hindari."],"tips":["Yang mengemudi harus orang terlatih dan tercatat, bukan sekadar yang bisa mengemudi; aktifkan 4WD di jalan kebun berkerikil atau licin.","Jarak pandang kurang dari 50 meter akibat debu atau asap berarti berhenti di tempat aman dengan lampu menyala."],"perhatian":["Rollover di jalan kebun sering terjadi pada jarak pandang rendah dengan pengemudi yang belum pernah mengikuti pelatihan defensive driving.","Takut ganti rugi mengubah cerita kronologi dan membuat perbaikan salah sasaran."],"apd":{"wajib":"Sabuk pengaman, safety shoes, rompi reflektif.","tambahan":"Helm, sarung tangan medis, senter."},"darurat":{"potensi":"Kendaraan terguling, kebakaran kendaraan, korban terjepit, kecelakaan di jalan sepi tanpa sinyal.","respon":"Matikan mesin, keluar ke sisi aman, cek orang, pasang segitiga, telepon, foto.","alat":"Segitiga pengaman, APAR, kotak P3K, senter, radio/telepon, alat komunikasi cadangan."},"catatan":"Insiden lalu lintas wajib dilaporkan sebagai insiden perusahaan, bukan urusan pribadi pengemudi. # BAGIAN C — LOKASI TERPENCIL, LISTRIK, KETINGGIAN, DAN DARURAT MEDIS (DRT)","dasar":["UU No. 22/2009 (LLAJ)","UU No. 1/1970","Pedoman P3K","praktik industri","UU No. 22/2009","Permenaker No. PER.03/MEN/1998","PP No. 50/2012 (investigasi dan tindak lanjut)"]},{"id":"09","title":"Personel Hilang Kontak atau Man Down di Lokasi Terpencil","steps":[{"n":1,"do":"Mencoba tiga jalur kontak dalam 10 menit: telepon, radio, dan rekan atau pihak pelanggan terdekat","items":[{"k":"wajib","t":"**Tetapkan status \"hilang kontak\" bila tiga jalur gagal dan catat jam terakhir berkomunikasi, tujuan, kendaraan, rute, dan jumlah orang**."},{"k":"lakukan","t":"Setiap perjalanan ke lokasi terpencil punya rencana perjalanan (rute, jam berangkat, jam tiba, jam check-in) yang diketahui satu orang di kantor."}]},{"n":2,"do":"Menghubungi kontak darurat pelanggan atau pengelola area untuk membantu menyisir jalur","items":[{"k":"lakukan","t":"Gunakan kontak dari kartu kontak darurat lokasi kerja (Tutorial 21); beri informasi rute terakhir dan ciri kendaraan."}]},{"n":3,"do":"Mengirim tim minimal 2 orang menyusuri rute terakhir membawa P3K, air, senter, dan bahan bakar cadangan","items":[{"k":"wajib","t":"**Tidak boleh mencari sendirian; tim minimal dua orang dengan alat komunikasi dan jam lapor**."},{"k":"lakukan","t":"Sepakati batas waktu dan jam lapor tim pencari."},{"k":"apd","t":"Helm, rompi reflektif, sepatu keselamatan, senter."}]},{"n":4,"do":"Bila ditemukan man down: memastikan area aman (gas, listrik, unit bergerak), cek sadar dan napas, tidak memindahkan bila tidak perlu","items":[{"k":"wajib","t":"**Pastikan aman untuk penolong sebelum mendekat; lanjut Tutorial 06**."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":5,"do":"Menaikkan ke Level 2 dan memberi tahu atasan bila belum ditemukan dalam 1 jam; menghubungi kepolisian atau Basarnas bila lebih dari 3 jam atau menjelang gelap","items":[{"k":"wajib","t":"**Eskalasi berdasarkan waktu, bukan perasaan: 1 jam ke atasan, 3 jam atau menjelang gelap ke kepolisian dan Basarnas (115)**."},{"k":"lakukan","t":"Larang bekerja sendirian pada pekerjaan berisiko tinggi (ruang terbatas, ketinggian, kelistrikan, bekerja di bawah unit) tanpa pengecualian."}]}],"aturan":["Tiga jalur kontak, 10 menit.","Dua orang untuk mencari.","Eskalasi berdasarkan jam."],"siap":["Rencana perjalanan dan jam check-in tercatat.","Kartu kontak darurat lokasi kerja terisi.","Larangan kerja sendirian pada pekerjaan berisiko tinggi ditegakkan."],"jangan":["Menunggu lebih dari 30 menit sebelum menganggap ada masalah — hindari dengan jam check-in yang disepakati.","Mencari sendirian — hindari."],"tips":["Cek sinyal sebelum mulai kerja di lokasi jauh; bila tidak ada sinyal, sepakati jam check-in ke kantor.","Sebut lokasi dengan koordinat atau patokan yang bisa dicari, bukan \"di kebun blok sana\"."],"perhatian":["Kelompok kerja kecil (2-4 orang) jauh dari kantor adalah kondisi paling rentan karena bantuan lama datang."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, rompi reflektif.","tambahan":"Senter/head lamp, jaket, perlengkapan komunikasi cadangan."},"darurat":{"potensi":"Personel hilang kontak, cedera tanpa saksi, kendaraan terjebak di medan berat.","respon":"Tiga jalur kontak, hubungi pelanggan, kirim tim dua orang, siapkan P3K dan air.","alat":"Radio/telepon satelit bila tersedia, P3K, senter, air, bahan bakar cadangan, peta rute."},"catatan":"Pencegahan lebih penting daripada pencarian: rencana perjalanan, jam check-in, dan larangan bekerja sendirian.","dasar":["PP No. 50/2012","praktik industri","Praktik industri","Permenaker No. 15/2008"]},{"id":"10","title":"Sengatan Listrik dan Busur Api Listrik","steps":[{"n":1,"do":"Tidak menyentuh korban; memutus sumber listrik dari panel, MCB, atau master switch","items":[{"k":"wajib","t":"**Jangan sentuh korban sebelum sumber diputus; bila tidak bisa, dorong korban dengan benda kering non-konduktif sambil berdiri di alas kering**."},{"k":"lakukan","t":"Tegangan tinggi: jangan mendekat kurang dari 10 meter sebelum dinyatakan mati oleh petugas berwenang."},{"k":"apd","t":"Sarung tangan isolasi, alas kaki isolasi."}]},{"n":2,"do":"Memanggil bantuan dan memeriksa napas dan nadi; memulai RJP dan memakai AED bila perlu","items":[{"k":"wajib","t":"**Segera RJP dan AED bila tidak sadar dan tidak bernapas normal**; lanjut Tutorial 06."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":3,"do":"Mencari dua luka (titik masuk dan titik keluar) dan menutup luka bakar dengan kain bersih","items":[{"k":"lakukan","t":"Aliri luka bakar air bersih bila kecil, tutup kain bersih tidak berbulu; jangan memecah lepuhan."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":4,"do":"Membawa semua korban sengatan listrik ke rumah sakit walau mengaku baik-baik saja","items":[{"k":"wajib","t":"**Semua korban sengatan listrik wajib diperiksa di rumah sakit**; catat jam kejadian dan tegangan bila diketahui."}]},{"n":5,"do":"Mengamankan panel dan area, memberi tanda dilarang menyalakan kembali (LOTO) sampai diperiksa","items":[{"k":"wajib","t":"**Pasang LOTO pada panel yang terdampak dan jangan menyalakan sebelum diperiksa petugas listrik berwenang**; lanjut Tutorial 20."},{"k":"apd","t":"Sarung tangan isolasi."}]}],"aturan":["Putus sumber listrik dulu.","Semua korban sengatan listrik ke rumah sakit.","LOTO sampai diperiksa."],"siap":["Panel dan MCB berlabel dan mudah dijangkau.","AED tersedia dan petugas terlatih RJP.","Alat uji tegangan dan alas isolasi tersedia."],"jangan":["Menyentuh korban yang masih tersambung arus — hindari.","Membiarkan korban \"tidak apa-apa\" pulang tanpa diperiksa — hindari."],"tips":["Ledakan busur api pada panel dan sistem kelistrikan unit memerlukan jarak dan APD arc flash sesuai tingkat energi; jangan mendekat sebelum dinyatakan aman."],"perhatian":["Sengatan listrik sering menghentikan jantung, dan luka luar yang kecil menyembunyikan kerusakan dalam."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, sarung tangan kerja.","tambahan":"Sarung tangan dan alas kaki isolasi, pelindung wajah arc flash."},"darurat":{"potensi":"Henti jantung, luka bakar listrik, kebakaran akibat korsleting.","respon":"Putus listrik, RJP dan AED, aliri luka bakar, ke rumah sakit.","alat":"AED, sarung tangan isolasi, tongkat isolasi, APAR CO₂/powder, kotak P3K."},"catatan":"Semua korban sengatan listrik wajib dibawa ke rumah sakit karena gangguan irama jantung bisa muncul belakangan.","dasar":["Permenaker No. 12/2015","UU No. 1/1970","Pedoman RJP AHA/ERC","Permenaker No. 15/2008","Pedoman P3K","praktik industri","OSHA 29 CFR 1910.147"]},{"id":"11","title":"Penyelamatan dari Ketinggian dan Ruang Terbatas","steps":[{"n":1,"do":"Tidak masuk sendiri ke ruang terbatas, memanggil bantuan dan tim penyelamat terlatih","items":[{"k":"wajib","t":"**JANGAN MASUK tanpa alat dan tim terlatih; aturan tanpa pengecualian**; di site pelanggan gunakan tim rescue mereka."},{"k":"lakukan","t":"Rencana penyelamatan wajib ada sebelum izin kerja diterbitkan; tanpa alat dan tim rescue, izin kerja tidak layak diterbitkan."},{"k":"apd","t":"Tidak memasuki ruang tanpa SCBA dan harness sesuai prosedur."}]},{"n":2,"do":"Berbicara terus dengan korban dari luar, memantau kesadaran, dan mencatat waktu","items":[{"k":"lakukan","t":"Satu orang khusus memantau dan mencatat jam; pastikan komunikasi radio atau tali isyarat."}]},{"n":3,"do":"Ruang terbatas: meningkatkan ventilasi, mengukur kadar gas atau oksigen bila ada alat, dan tidak menyalakan sumber percikan","items":[{"k":"wajib","t":"**Ukur atmosfer sebelum ada yang masuk; ventilasi paksa dan tanpa sumber percikan**."},{"k":"lakukan","t":"Gas detector terkalibrasi, blower anti-percikan."},{"k":"apd","t":"SCBA bagi tim penyelamat."}]},{"n":4,"do":"Korban tergantung pada harness: menurunkan secepat mungkin (tidak lebih dari sekitar 15 menit) dan membantu menopang kaki","items":[{"k":"wajib","t":"**Turunkan dalam waktu sesingkat mungkin; bila belum bisa, bantu korban menopang kaki pada tali atau pijakan**."},{"k":"lakukan","t":"Tali dan perangkat penyelamatan dikaji sebelum izin kerja ketinggian."},{"k":"apd","t":"Full body harness dan lanyard terpasang pada titik angkur."}]},{"n":5,"do":"Setelah korban keluar: membaringkan dan menangani sebagai kondisi kritis, tetap ke fasilitas medis walau tampak sadar penuh","items":[{"k":"wajib","t":"**Semua korban ketinggian dan ruang terbatas ke fasilitas medis**; lanjut Tutorial 06."},{"k":"apd","t":"Sarung tangan medis."}]}],"aturan":["Jangan masuk, panggil tim penyelamat.","Ukur atmosfer sebelum masuk.","Turunkan korban harness secepat mungkin."],"siap":["Rencana penyelamatan tertulis dan alat tersedia sebelum izin kerja.","Tim rescue terlatih dan dikenal waktu responsnya.","Gas detector dan SCBA tersedia di lokasi."],"jangan":["Penolong masuk tanpa alat — hindari tanpa pengecualian."],"tips":["Kalau lokasi punya pekerjaan di ketinggian atau ruang terbatas, rencana penyelamatan harus ada sebelum izin kerja, bukan mengandalkan panggilan damkar."],"perhatian":["Korban yang tergantung pada harness dapat mengalami kondisi kritis dalam hitungan menit."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, full body harness untuk ketinggian.","tambahan":"SCBA, gas detector personal, tali penyelamat."},"darurat":{"potensi":"Korban pingsan di tangki atau pit, korban tergantung di harness, jatuh dari struktur.","respon":"Jangan masuk, panggil tim rescue, ventilasi, pantau korban, turunkan korban harness.","alat":"SCBA, tripod dan winch rescue, harness cadangan, gas detector, tandu, radio."},"catatan":"Penyelamatan ruang terbatas dan ketinggian adalah pekerjaan tim terlatih, bukan relawan di tempat.","dasar":["Permenaker No. 9/2016 (K3 pada pekerjaan di ketinggian)","UU No. 1/1970","Praktik industri","Permenaker No. 9/2016 (perlu verifikasi untuk ruang terbatas)","praktik industri","Permenaker No. 9/2016","Permenaker No. 15/2008"]},{"id":"12","title":"Darurat Medis Bukan Kecelakaan (Jantung, Stroke, Kejang, Panas, dan Gigitan Ular)","steps":[{"n":1,"do":"Memanggil first aider dan ambulans lebih dulu tanpa menunggu \"lihat dulu sebentar\"; tidak sadar dan tidak bernapas normal berarti RJP dan AED","items":[{"k":"wajib","t":"**Panggil bantuan lebih dulu, RJP segera bila tidak bernapas normal**; lanjut Tutorial 06."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":2,"do":"Nyeri dada, keringat dingin: mendudukkan setengah bersandar, melonggarkan pakaian, dan tidak membiarkan berjalan sendiri","items":[{"k":"wajib","t":"**Korban istirahat total, bantuan ambulans dipanggil, AED disiapkan**."}]},{"n":3,"do":"Curiga stroke (wajah perot, satu tangan lemah, bicara pelo): mencatat jam mulai gejala, tidak memberi makan atau minum, ke rumah sakit secepatnya","items":[{"k":"wajib","t":"**Catat jam mulai gejala dan segera bawa ke rumah sakit; jangan beri makan atau minum**."}]},{"n":4,"do":"Kejang: menjauhkan benda keras, memberi alas kepala, tidak menahan dan tidak memasukkan apa pun ke mulut, memiringkan badan setelah kejang berhenti","items":[{"k":"wajib","t":"**Jangan menahan gerakan dan jangan memasukkan benda ke mulut**; hitung lama kejang, panggil ambulans bila lebih dari 5 menit atau berulang."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":5,"do":"Kelelahan panas: memindahkan ke teduh, melonggarkan pakaian, mendinginkan dengan air dan kipas, memberi minum bila sadar penuh; kulit panas kering dan bingung berarti darurat","items":[{"k":"wajib","t":"**Bila kulit panas kering atau korban bingung dan pingsan, dinginkan agresif sambil menuju rumah sakit**."},{"k":"lakukan","t":"Pencegahan: air minum terjangkau, jeda teduh terjadwal, aturan kerja-istirahat lebih longgar pada siang terik; tanda awal: urine pekat, kram, pusing, mual."},{"k":"apd","t":"Topi/helm berventilasi, pakaian ringan menyerap keringat."}]},{"n":6,"do":"Gigitan ular atau sengatan: menenangkan dan membatasi gerak korban, mengimobilisasi bagian tergigit, melepas cincin, jam, dan sepatu, segera ke rumah sakit","items":[{"k":"wajib","t":"**Imobilisasi dan segera ke rumah sakit; JANGAN mengikat kencang, menyayat, menyedot, memberi kopi atau alkohol, atau mengejar ular**; catat jam gigitan dan ciri ular."},{"k":"lakukan","t":"Sengatan tawon: keluarkan sengat dengan menggeser kartu, kompres dingin; bengkak wajah atau sesak berarti darurat."},{"k":"apd","t":"Sepatu boot dan celana panjang di area semak."}]}],"aturan":["Panggil bantuan dulu, lalu tangani.","Catat jam mulai gejala.","Gigitan ular: imobilisasi, jangan mengikat kencang."],"siap":["Petugas P3K dan AED tersedia tiap shift.","Rujukan rumah sakit terdekat dan waktu tempuh diketahui.","Air minum dan area teduh tersedia di site panas."],"jangan":["Menunggu \"lihat dulu\" sebelum menelepon — hindari.","Memberi minum pada korban curiga stroke — hindari."],"tips":["Kotak P3K kendaraan servis lapangan perlu ditambah pembalut tekan, gunting, selimut darurat, dan air bersih untuk irigasi mata."],"perhatian":["Darurat medis tidak harus terkait pekerjaan, tetapi tetap tanggung jawab tim di tempat sampai ambulans tiba."],"apd":{"wajib":"Sarung tangan medis, safety helmet, safety shoes toe cap.","tambahan":"Sepatu boot (area ular), pakaian ringan."},"darurat":{"potensi":"Serangan jantung, stroke, kejang, heat stroke, gigitan ular, anafilaksis.","respon":"Panggil ambulans, RJP bila perlu, imobilisasi, dinginkan, catat jam gejala.","alat":"AED, kotak P3K, oralit, air bersih, selimut, tandu."},"catatan":"Pencegahan lebih efektif: air minum, jeda teduh, dan pemeriksaan kesehatan berkala. # BAGIAN D — BENCANA ALAM, ASAP, DAN KEAMANAN (DRT)","dasar":["Permenaker No. 15/2008","Pedoman RJP AHA/ERC","Pedoman P3K","Permenaker No. 5/2018 (lingkungan kerja - iklim kerja)","praktik industri"]},{"id":"13","title":"Gempa Bumi dan Tsunami","steps":[{"n":1,"do":"Saat guncangan: merunduk, melindungi kepala dan leher, masuk ke bawah meja kokoh, bertahan; jauhi kaca, rak tinggi, lemari parts, dan panel listrik","items":[{"k":"wajib","t":"**Jangan berlari keluar saat masih berguncang; merunduk, lindungi, bertahan**."},{"k":"lakukan","t":"Di luar: jauhi bangunan dan tiang, jongkok di area terbuka. Di kendaraan atau unit: berhenti di tempat terbuka, tetap di dalam, jangan berhenti di bawah jembatan atau tebing."},{"k":"apd","t":"Helm, bila ada."}]},{"n":2,"do":"Setelah guncangan berhenti: evakuasi lewat tangga ke titik kumpul terbuka, waspada pecahan kaca dan material menggantung","items":[{"k":"wajib","t":"**Jangan memakai lift, jangan masuk kembali sebelum bangunan diperiksa kelaikannya**."},{"k":"lakukan","t":"Warden menyisir dan menghitung orang; first aider menyiapkan pos pertolongan di titik kumpul."},{"k":"apd","t":"Helm, sepatu keselamatan."}]},{"n":3,"do":"Mematikan listrik, gas, dan pompa bahan bakar; tidak menyalakan api atau saklar bila tercium bau gas","items":[{"k":"wajib","t":"**Matikan listrik, gas, dan pompa BBM; tidak ada api atau saklar bila bau gas**."},{"k":"lingkungan","t":"Periksa tangki dan drum, bendung tumpahan (Tutorial 05)."},{"k":"apd","t":"Sarung tangan, helm."}]},{"n":4,"do":"Lokasi pesisir: segera menuju tempat tinggi atau menjauh dari garis pantai tanpa menunggu sirene; berjalan kaki bila memungkinkan; tidak kembali mengambil barang","items":[{"k":"wajib","t":"**Gempa kuat di dekat pantai adalah peringatan alam; segera ke tempat tinggi, tidak menunggu pengumuman, bertahan sampai pernyataan resmi berakhir (gelombang berikutnya sering lebih besar)**."},{"k":"lakukan","t":"Cek informasi resmi BMKG, bukan pesan berantai; kenali jalur evakuasi tsunami setempat."}]},{"n":5,"do":"Melaporkan status: nama, jumlah orang, lokasi, kondisi; menghasilkan daftar personel di wilayah terdampak beserta status aman atau belum terhubung dalam 60 menit","items":[{"k":"wajib","t":"**Setiap cabang atau lokasi dapat menghasilkan daftar personel dengan status aman atau belum terhubung dalam 60 menit**."},{"k":"lakukan","t":"Pesan status singkat ke atasan; kondisi orang, bangunan, unit, kelistrikan; lanjut Tutorial 20."}]}],"aturan":["Merunduk, lindungi, bertahan.","Setelah berhenti: tangga, titik kumpul, hitung orang.","Gempa kuat di pantai: langsung naik."],"siap":["Titik kumpul terbuka dan jalur evakuasi tsunami diketahui semua personel.","Daftar personel dan kontak dapat dihasilkan dalam 60 menit.","Rak dan lemari tinggi diikat."],"jangan":["Berlari keluar saat berguncang — hindari.","Mengandalkan pesan berantai untuk peringatan tsunami — hindari; pakai sumber resmi."],"tips":["Kode Hitam untuk gempa baru dibunyikan setelah guncangan berhenti.","Periksa dinding retak, atap, dan struktur rak sebelum bangunan dipakai lagi."],"perhatian":["Kebutuhan terbesar manajemen pada jam pertama bukan analisa, melainkan daftar personel beserta statusnya."],"apd":{"wajib":"Safety helmet, safety shoes toe cap.","tambahan":"Senter, masker debu."},"darurat":{"potensi":"Bangunan retak atau roboh, kebakaran susulan, kebocoran gas, tsunami.","respon":"Berlindung, evakuasi, matikan utilitas, hitung orang, laporkan status.","alat":"Radio/telepon cadangan, kotak P3K, senter, daftar personel, air minum."},"catatan":"Cek informasi BMKG untuk peringatan tsunami dan gempa susulan.","dasar":["UU No. 24/2007 (penanggulangan bencana)","praktik industri (merunduk-lindungi-bertahan)","UU No. 24/2007","PP No. 50/2012","Permenaker No. 12/2015","PP No. 22/2021","BMKG","praktik industri"]},{"id":"14","title":"Banjir, Angin Kencang, Petir, dan Pohon Tumbang","steps":[{"n":1,"do":"Banjir: mematikan listrik area terdampak dari panel sebelum air mencapai stop kontak dan panel bawah","items":[{"k":"wajib","t":"**Matikan listrik area terdampak dari panel sebelum air naik; jangan berjalan atau berkendara menembus arus (air setinggi lutut yang mengalir dapat menjatuhkan orang dewasa)**."},{"k":"lingkungan","t":"Amankan drum, oli, dan limbah B3 agar tidak hanyut; tumpahan akibat banjir tetap tanggung jawab perusahaan."},{"k":"apd","t":"Sepatu boot, jaket pelampung bila perlu."}]},{"n":2,"do":"Memindahkan orang lebih dulu, baru dokumen, parts, dan unit ke tempat lebih tinggi selama akses masih aman","items":[{"k":"lakukan","t":"Bila akses terputus, bertahan di lantai atas yang aman, laporkan jumlah orang yang bertahan, jangan berenang keluar."},{"k":"apd","t":"Sepatu boot."}]},{"n":3,"do":"Petir dan angin kencang: menghentikan kerja ketinggian, pengangkatan crane, dan pekerjaan di area terbuka; masuk ke bangunan berdinding penuh atau kabin tertutup","items":[{"k":"wajib","t":"**Aturan 30-30: bila jarak kilat ke guruh kurang dari 30 detik masuk bangunan; keluar kembali paling cepat 30 menit setelah guruh terakhir; turunkan boom dan attachment**."},{"k":"lakukan","t":"Jangan berteduh di bawah pohon, gudang terbuka, atau dekat struktur logam tinggi; menjauh dari reklame, atap seng, dan tiang listrik."}]},{"n":4,"do":"Setelah reda atau air surut: memeriksa kabel jatuh (anggap bertegangan), atap rusak, pohon miring; tidak menyalakan listrik sebelum instalasi diperiksa dan kering","items":[{"k":"wajib","t":"**Jangan menyalakan listrik atau menghidupkan unit terendam sebelum diperiksa teknisi**; buang makanan yang terkena air banjir dan disinfeksi area kerja."},{"k":"apd","t":"Sepatu boot, sarung tangan, masker."}]}],"aturan":["Listrik mati dulu, orang dipindahkan dulu.","30-30 untuk petir.","Tidak menyalakan listrik sebelum diperiksa."],"siap":["Pemantauan prakiraan cuaca dan peringatan dini sebelum pekerjaan terbuka.","Jalur evakuasi tinggi diketahui.","Larangan kerja ketinggian dan crane saat petir dan angin kencang."],"jangan":["Menerobos arus dengan kendaraan — hindari.","Berteduh di bawah pohon saat petir — hindari."],"tips":["Tutup selokan terbuka yang tidak terlihat; pasang tanda di area tergenang.","Pindahkan unit dan kendaraan ke tempat lebih tinggi selama akses aman."],"perhatian":["Banjir membawa dua bahaya sekaligus: listrik dan tumpahan B3 yang hanyut."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, jas hujan.","tambahan":"Sepatu boot, jaket pelampung, senter."},"darurat":{"potensi":"Orang terjebak air, sengatan listrik, tertimpa pohon atau atap, tumpahan hanyut.","respon":"Matikan listrik, pindahkan orang, hentikan kerja terbuka, laporkan jumlah orang bertahan.","alat":"Pelampung, tali, radio, senter, kotak P3K."},"catatan":"Pakai prakiraan cuaca dan peringatan dini BMKG sebagai dasar menghentikan kerja terbuka.","dasar":["UU No. 24/2007","Permenaker No. 12/2015","PP No. 22/2021","Permenaker No. 9/2016 (kerja di ketinggian - hentikan saat cuaca ekstrem)","praktik industri","Permenaker No. 5/2018"]},{"id":"15","title":"Kebakaran Lahan dan Kabut Asap","steps":[{"n":1,"do":"Melaporkan titik api ke pengelola lahan atau pelanggan dan ke kantor tanpa berasumsi sudah ada yang melapor","items":[{"k":"wajib","t":"**Lapor titik api; jangan memadamkan api lahan sendiri karena arah angin berubah cepat dan orang mudah terkepung**."},{"k":"lakukan","t":"Siapkan dua jalur keluar dan titik kumpul di luar arah angin."},{"k":"apd","t":"Masker, helm."}]},{"n":2,"do":"Menghentikan perjalanan bila jarak pandang kurang dari 50 meter; menepi di tempat aman dengan lampu menyala","items":[{"k":"wajib","t":"**Jarak pandang kurang dari 50 meter berarti berhenti di tempat aman, bukan memperlambat di tengah jalan**; wajib lapor posisi tiap jam untuk perjalanan lintas kabupaten pada periode asap."},{"k":"lakukan","t":"Larangan perjalanan malam pada periode asap; lanjut Tutorial 08 bila terjadi kecelakaan."},{"k":"apd","t":"Rompi reflektif."}]},{"n":3,"do":"Menjauhkan unit, kendaraan, dan drum bahan bakar dari arah rambatan api; membuat jarak bersih bila memungkinkan","items":[{"k":"lakukan","t":"Pindahkan aset ke arah berlawanan dengan api, siapkan APAR dan air."},{"k":"lingkungan","t":"Amankan drum dan limbah B3."},{"k":"apd","t":"Helm, masker."}]},{"n":4,"do":"Melindungi pernapasan: menutup jendela dan pintu, membatasi aktivitas luar ruangan, menyediakan air minum lebih banyak, dan memantau kualitas udara","items":[{"k":"wajib","t":"**Pakai masker partikulat (N95/KN95) pada indeks tidak sehat; batasi pekerjaan berat di luar ruangan; kelompok sensitif tetap di dalam**."},{"k":"lakukan","t":"Pantau indeks kualitas udara (widget cuaca di JASMIN) dan hentikan kerja luar ruangan pada kategori sangat tidak sehat atau berbahaya."},{"k":"apd","t":"Masker N95/KN95."}]}],"aturan":["Lapor titik api, jangan padamkan sendiri.","Jarak pandang kurang dari 50 meter: berhenti.","Masker N95 pada udara tidak sehat."],"siap":["Aturan musiman asap diterbitkan sebelum kemarau.","Dua jalur keluar dan titik kumpul di luar arah angin.","Masker partikulat tersedia di lokasi."],"jangan":["Melanjutkan perjalanan \"pelan-pelan\" di jarak pandang rendah — hindari."],"tips":["Terbitkan aturan musiman: batas jarak pandang minimum, larangan perjalanan malam, wajib lapor posisi tiap jam."],"perhatian":["Kabut asap adalah faktor penyumbang kecelakaan lalu lintas yang nyata; bahayanya ganda: lalu lintas dan kesehatan."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, masker N95/KN95.","tambahan":"Kacamata tertutup, rompi reflektif."},"darurat":{"potensi":"Api lahan mendekati lokasi, jarak pandang nol di jalan, banyak pekerja sesak napas.","respon":"Lapor, berhenti di tempat aman, evakuasi ke luar arah angin, bagikan masker.","alat":"Masker N95, air minum, radio, APAR, kotak P3K."},"catatan":"Gabungkan dengan Tutorial 08 untuk perjalanan di jalan berkabut asap.","dasar":["UU No. 24/2007","praktik industri","UU No. 22/2009","Kepmenaker No. 186/1999","PP No. 22/2021","Permenaker No. 5/2018"]},{"id":"16","title":"Gangguan Keamanan (Kerusuhan, Blokade, Ancaman Bom, Perampokan dan Pembegalan)","steps":[{"n":1,"do":"Kerusuhan atau unjuk rasa: semua orang masuk bangunan, menjauhi pagar dan gerbang, mengunci akses, menghentikan penerimaan tamu dan pengiriman","items":[{"k":"wajib","t":"**Security berkomunikasi, tidak berkonfrontasi; satu juru bicara; keselamatan orang di atas aset; bila massa masuk, tidak melawan dan mundur ke area aman**."},{"k":"lakukan","t":"Hubungi kepolisian dan pengelola kawasan atau pelanggan; personel yang terjebak di luar menepi ke lokasi aman dan melapor posisi."}]},{"n":2,"do":"Ancaman bom lewat telepon: tetap tenang, tidak menutup telepon, mencatat kata persis, kapan, di mana, bentuk, suara latar, logat, jam dan nomor","items":[{"k":"wajib","t":"**Biarkan penelepon bicara, ulur waktu dengan bertanya berulang, beri isyarat rekan memanggil QSHE dan security tanpa memutus telepon; keputusan evakuasi ada pada Chief of Emergency**."},{"k":"lakukan","t":"Serahkan catatan ke QSHE dan security; sisir area bersama pihak berwenang; Kode Biru."}]},{"n":3,"do":"Menemukan benda atau paket mencurigakan: tidak menyentuh, memindahkan, membuka, atau menyiram air; tidak memakai HP atau HT dalam radius 15 meter; mengosongkan area","items":[{"k":"wajib","t":"**Jangan sentuh, jangan pakai HP atau HT dalam 15 meter, kosongkan area, tunggu tim penjinak kepolisian**."},{"k":"lakukan","t":"Catat siapa yang menemukan, jam berapa, apakah benda sempat tersentuh atau berpindah."}]},{"n":4,"do":"Perampokan, pembegalan, atau ancaman kekerasan: menyerahkan barang, mematuhi pelaku, mengingat ciri, lalu mengunci area, menelepon 110 dan atasan","items":[{"k":"wajib","t":"**Serahkan barang; uang, kendaraan, laptop dapat diganti, nyawa tidak; jangan melawan dan jangan mengejar**."},{"k":"lakukan","t":"Setelah pelaku pergi, jangan bersihkan apa pun; periksa kondisi semua orang termasuk yang tampak baik; laporkan sebagai insiden perusahaan; sediakan pendampingan dan penilaian ulang rute atau jadwal perjalanan."}]}],"aturan":["Nyawa di atas aset.","Jangan sentuh benda mencurigakan.","Satu juru bicara."],"siap":["Akses gerbang dapat dikunci cepat.","Daftar posisi personel di lapangan dapat dihasilkan cepat.","Prosedur penerima telepon ancaman tersedia di meja resepsionis."],"jangan":["Menantang atau berdebat dengan massa — hindari.","Menggunakan HP dekat benda mencurigakan — hindari."],"tips":["Kode Kuning untuk kerusuhan dan blokade, Kode Biru untuk ancaman bom.","Blokade jalan atau akses site: jangan menerobos, menepi dan melapor posisi."],"perhatian":["Kejadian keamanan yang tidak dilaporkan cenderung berulang di lokasi yang sama."],"apd":{"wajib":"Tidak ada APD khusus; ikuti APD pekerjaan.","tambahan":"Tidak ada."},"darurat":{"potensi":"Massa masuk area, ledakan, penyanderaan, kekerasan terhadap personel.","respon":"Masuk bangunan, kunci akses, hubungi polisi, hitung personel, jangan melawan.","alat":"Telepon darurat, daftar kontak polisi dan pengelola kawasan, daftar personel, formulir catatan telepon ancaman."},"catatan":"Perlakuan khusus: personel yang menjadi korban atau saksi diberi waktu pemulihan dan pendampingan.","dasar":["UU No. 1/1970","praktik industri","Praktik industri","koordinasi kepolisian"]},{"id":"17","title":"Keracunan Makanan Massal","steps":[{"n":1,"do":"Menghentikan konsumsi makanan tersebut di seluruh lokasi dan mengumumkan segera","items":[{"k":"wajib","t":"**Dua orang atau lebih mual, muntah, diare setelah makan dari sumber sama berarti hentikan konsumsi seluruh lokasi dan bunyikan Kode Putih**."},{"k":"apd","t":"Sarung tangan saat menangani sisa makanan."}]},{"n":2,"do":"Mengamankan sampel makanan, kemasan, dan sisa masakan di wadah tertutup yang didinginkan","items":[{"k":"lakukan","t":"Simpan sampel dan catat sumber katering; sampel makanan harian vendor disimpan 24 jam dan masuk kontrak."},{"k":"apd","t":"Sarung tangan."}]},{"n":3,"do":"Mengumpulkan korban di satu tempat sejuk dekat toilet, mencatat nama, jam makan, jam gejala, dan menu","items":[{"k":"lakukan","t":"Beri minum air atau oralit sedikit-sedikit bila sadar; jangan memaksa muntah."},{"k":"apd","t":"Sarung tangan medis."}]},{"n":4,"do":"Mengirim korban dengan muntah terus, diare berdarah, lemas berat, atau sesak ke klinik atau rumah sakit; melapor Level 2","items":[{"k":"wajib","t":"**Utamakan yang paling lemah; laporkan sebagai Level 2 dan hubungi dinas kesehatan bila korban banyak**."},{"k":"lakukan","t":"Audit dapur dan vendor katering: rantai dingin, suhu penyajian, kesehatan penjamah makanan."}]}],"aturan":["Hentikan konsumsi, amankan sampel, catat.","Utamakan korban paling lemah."],"siap":["Sampel makanan harian disimpan.","Daftar vendor katering dan kontak diketahui."],"jangan":["Membuang sisa makanan sebelum diambil sampel — hindari."],"tips":["Kewajiban penyimpanan sampel harian sebaiknya masuk kontrak vendor katering."],"perhatian":["Kejadian ini hampir selalu melibatkan katering dan pihak luar sehingga perlu pelaporan dan koordinasi."],"apd":{"wajib":"Sarung tangan medis.","tambahan":"Masker."},"darurat":{"potensi":"Banyak korban keracunan sekaligus, dehidrasi berat.","respon":"Hentikan konsumsi, kumpulkan korban, oralit, rujuk yang berat.","alat":"Oralit, air minum, kotak P3K, kantong sampel dan cool box."},"catatan":"Setelah kejadian lakukan audit dapur dan vendor. # BAGIAN E — EVAKUASI, KESIAPAN ALAT, DAN PASCA DARURAT (DRT)","dasar":["Permenaker No. 5/2018","praktik industri","Praktik industri","perlu verifikasi regulasi higiene sanitasi setempat","Pedoman P3K","PP No. 50/2012"]},{"id":"18","title":"Evakuasi, Titik Kumpul, dan Penghitungan Personel","steps":[{"n":1,"do":"Chief of Emergency (COE) menetapkan keadaan darurat dan memerintahkan evakuasi; alarm dibunyikan, semua kegiatan dihentikan","items":[{"k":"wajib","t":"**COE dan penggantinya ditunjuk tertulis untuk setiap shift; keputusan evakuasi tidak menunggu konfirmasi berlapis**."},{"k":"lakukan","t":"Satu kata kode dan satu nada alarm yang dipahami semua orang."}]},{"n":2,"do":"Warden menyisir area, memastikan toilet, gudang, dan ruang tertutup kosong, lalu menutup pintu tanpa mengunci","items":[{"k":"wajib","t":"**Tutup pintu (jangan dikunci) untuk memperlambat asap; jangan masuk kembali untuk mengambil barang**."},{"k":"lakukan","t":"Rompi warden dan peluit; satu warden untuk setiap area atau lantai."},{"k":"apd","t":"Rompi warden."}]},{"n":3,"do":"Personel bergerak lewat jalur evakuasi ke titik kumpul, berjalan cepat tanpa berlari, tidak memakai lift","items":[{"k":"wajib","t":"**Jalur dan pintu darurat bebas hambatan setiap saat; titik kumpul di area terbuka, jauh dari bangunan, jalur kendaraan, dan tangki bahan bakar**."},{"k":"lakukan","t":"Tamu dan kontraktor ikut diarahkan; bantu penyandang disabilitas dan orang sakit."}]},{"n":4,"do":"Menghitung personel di titik kumpul berdasarkan daftar hadir, tamu, dan kontraktor; melapor jumlah dan nama yang belum ditemukan ke COE","items":[{"k":"wajib","t":"**Daftar hadir, buku tamu, dan daftar kontraktor tersedia di titik kumpul; nama yang belum ditemukan dilaporkan ke COE, bukan dicari sendiri oleh warden**."},{"k":"lakukan","t":"Tim pencarian dan penyelamatan hanya bergerak atas perintah COE."}]},{"n":5,"do":"Evakuasi dinyatakan selesai dan area dinyatakan aman oleh COE bersama pihak berwenang; personel tidak kembali sebelum pernyataan resmi","items":[{"k":"wajib","t":"**Kembali ke area kerja hanya setelah COE menyatakan aman**."},{"k":"lakukan","t":"Latihan evakuasi minimal sekali dalam setahun per lokasi dan hasilnya dievaluasi; lanjut Tutorial 20."}]}],"aturan":["Hentikan, keluar, kumpul, hitung.","Tidak ada yang kembali tanpa izin COE."],"siap":["Daftar peran darurat tertulis, termasuk pengganti per shift.","Daftar hadir dan tamu dapat dibawa ke titik kumpul.","Denah evakuasi terpasang dan latihan tahunan terjadwal."],"jangan":["Berlari atau memakai lift — hindari.","Kembali mengambil barang — hindari.","Warden mencari korban sendirian — hindari; laporkan ke COE."],"tips":["Peran minimum tim darurat: COE, warden, regu pemadam, first aider, security, tim komunikasi, tim tumpahan B3, dan petugas utilitas. Satu orang boleh merangkap bila lokasi kecil, tetapi tertulis jelas.","Sebelum keluar, ingat urutan: hentikan alat, matikan engine, ambil HP, keluar."],"perhatian":["Titik kumpul yang tidak diketahui personel baru dan tamu adalah penyebab umum penghitungan gagal."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, rompi warden untuk warden.","tambahan":"Peluit, senter, megafon."},"darurat":{"potensi":"Panik massal, orang tertinggal, jalur terblokir.","respon":"Alarm, evakuasi, hitung, laporkan ke COE.","alat":"Alarm, denah evakuasi, rompi warden, peluit, daftar hadir, megafon."},"catatan":"Sesuaikan jumlah warden dan titik kumpul dengan jumlah personel dan luas lokasi.","dasar":["PP No. 50/2012","Kepmenaker No. 186/1999","praktik industri"]},{"id":"19","title":"Inspeksi Kesiapan Alat Darurat (APAR, Hidran, Alarm, P3K, Eyewash, Spill Kit)","steps":[{"n":1,"do":"Menyiapkan daftar periksa dan memeriksa APAR: tekanan pada indikator hijau, segel pin utuh, selang tidak retak, tidak terhalang, tag terisi, dan masa isi ulang","items":[{"k":"wajib","t":"**Hanya APAR hijau dan terpasang pada tempatnya yang dianggap siap; APAR tidak layak diganti sementara sebelum ditarik**."},{"k":"lakukan","t":"Tanda APAR terlihat, tinggi pemasangan sesuai aturan, catatan inspeksi bulanan di tag."},{"k":"apd","t":"Sarung tangan."}]},{"n":2,"do":"Memeriksa hidran, selang, nozzle, pompa, dan kotak hidran: tidak terkunci, tidak berkarat, tekanan air tersedia","items":[{"k":"wajib","t":"**Uji alir dan tekanan sesuai jadwal; hidran dan selang tidak boleh terhalang atau dikunci**."},{"k":"lakukan","t":"Catat hasil uji, laporkan kerusakan sebagai temuan dengan batas waktu perbaikan."},{"k":"apd","t":"Sepatu keselamatan, sarung tangan."}]},{"n":3,"do":"Menguji alarm, lampu darurat, tanda jalur evakuasi, dan komunikasi darurat (telepon, radio, nomor darurat)","items":[{"k":"wajib","t":"**Uji alarm dan lampu darurat dengan pemberitahuan lebih dulu agar tidak dianggap kebakaran sungguhan**."},{"k":"lakukan","t":"Daftar nomor darurat dan kontak COE terpasang dan sesuai kondisi terbaru."}]},{"n":4,"do":"Memeriksa kotak P3K (isi lengkap, tidak kedaluwarsa), eyewash dan shower darurat (air mengalir bersih), serta spill kit (isi lengkap dan terjangkau)","items":[{"k":"wajib","t":"**Eyewash harus dapat dicapai kurang dari 10 detik dari area bahan kimia dan dialirkan mingguan; isi kotak P3K diperiksa sesuai Permenaker 15/2008**."},{"k":"lingkungan","t":"Spill kit berisi absorben, bantal serap, kantong limbah B3; sisa pakai dikelola sebagai limbah B3 (PP No. 22/2021)."},{"k":"apd","t":"Sarung tangan."}]},{"n":5,"do":"Mencatat hasil, memberi tag, menutup temuan, dan melaporkan rekap bulanan ke QSHE","items":[{"k":"wajib","t":"**Setiap temuan punya penanggung jawab dan tanggal tutup; temuan terlambat dieskalasi ke atasan**."},{"k":"lakukan","t":"Rekap bulanan: jumlah diperiksa, layak, tidak layak, dan umur temuan."}]}],"aturan":["Alat darurat harus siap, terlihat, dan terjangkau.","Temuan rusak tidak dibiarkan."],"siap":["Jadwal inspeksi bulanan dan uji berkala dijalankan.","Eyewash dialirkan mingguan.","Temuan memiliki batas waktu dan eskalasi."],"jangan":["Mencentang tanpa memeriksa tekanan — hindari.","Meletakkan barang di depan APAR atau hidran — hindari."],"tips":["Periksa setelah setiap kejadian darurat dan setelah relokasi ruangan.","APAR yang dipakai, walau sedikit, wajib diisi ulang."],"perhatian":["APAR tampak ada tetapi tidak berfungsi sama berbahayanya dengan tidak ada APAR."],"apd":{"wajib":"Safety shoes toe cap, sarung tangan.","tambahan":"Kacamata keselamatan."},"darurat":{"potensi":"APAR meledak atau terlepas, selang hidran pecah, kontak bahan kimia saat pengujian.","respon":"Hentikan pengujian, amankan area, bilas dengan air mengalir, laporkan.","alat":"Daftar periksa, tag inspeksi, kotak P3K, spill kit."},"catatan":"Frekuensi uji lanjutan (tahunan, riksa uji) mengikuti ketentuan peraturan dan perlu verifikasi pada kondisi lokasi.","dasar":["Permenaker No. 4/1980 (APAR)","Kepmenaker No. 186/1999","Permenaker No. 15/2008","PP No. 22/2021","Permenaker No. 5/2018","PP No. 50/2012 (pemantauan dan evaluasi)"]},{"id":"20","title":"Pasca Darurat (Pengamanan TKP, Pelaporan, dan Pemulihan)","steps":[{"n":1,"do":"Mengamankan tempat kejadian (TKP) dengan garis pembatas, tidak memindahkan unit atau barang kecuali untuk menyelamatkan nyawa atau mencegah bahaya lanjutan","items":[{"k":"wajib","t":"**Jaga TKP, foto sebelum apa pun dipindah, catat posisi, kondisi, dan saksi**."},{"k":"lakukan","t":"Hanya petugas berwenang yang masuk TKP."},{"k":"apd","t":"APD sesuai bahaya sisa."}]},{"n":2,"do":"Mendata korban, saksi, dan kerusakan; memberi pendampingan kepada korban dan saksi yang terguncang","items":[{"k":"lakukan","t":"Beri waktu istirahat, jangan membebani korban dan saksi dengan pertanyaan berulang; sediakan pendampingan psikologis."}]},{"n":3,"do":"Melaporkan: laporan awal segera (siapa, apa, kapan, di mana, kondisi), laporan tertulis 24 jam, dan laporan ke instansi sesuai ketentuan","items":[{"k":"wajib","t":"**Laporan awal tidak menunggu informasi lengkap; kecelakaan kerja dilaporkan ke instansi ketenagakerjaan dalam batas waktu yang berlaku (perlu verifikasi) dan tumpahan B3 ke instansi lingkungan bila memenuhi syarat**."},{"k":"lakukan","t":"Satu format laporan, satu juru bicara, tidak berspekulasi."}]},{"n":4,"do":"Memulihkan: memeriksa kelayakan bangunan dan alat, mengisi ulang APAR dan spill kit, membersihkan area, mengelola limbah B3, lalu membuka area bertahap","items":[{"k":"wajib","t":"**Area dibuka setelah dinyatakan aman oleh COE dan pihak berwenang; limbah kejadian dikelola sebagai limbah B3 bila terkontaminasi**."},{"k":"lingkungan","t":"Catat volume limbah dan penerima sah."},{"k":"apd","t":"Helm, sarung tangan, sepatu keselamatan, masker."}]},{"n":5,"do":"Evaluasi dalam 7 hari: investigasi penyebab, tindakan korektif, perbaikan prosedur, dan pelatihan ulang","items":[{"k":"wajib","t":"**Setiap tindakan korektif memiliki penanggung jawab dan tanggal; hasil dibagikan ke seluruh lokasi sejenis**."},{"k":"lakukan","t":"Sertakan pelajaran dalam Safety Moment dan latihan berikutnya."}]}],"aturan":["Amankan, dokumentasikan, laporkan.","Pulihkan hanya setelah dinyatakan aman."],"siap":["Format laporan awal, 24 jam, dan 7 hari tersedia.","Pendampingan bagi korban dan saksi tersedia.","Tindakan korektif dilacak sampai tutup."],"jangan":["Membersihkan TKP sebelum didokumentasi — hindari.","Menunda laporan awal menunggu data lengkap — hindari."],"tips":["Foto, catat, jangan pindahkan: tiga kata kerja pertama TKP.","Bagikan pelajaran ke lokasi lain, bukan hanya lokasi kejadian."],"perhatian":["Tekanan untuk segera beroperasi sering merusak bukti dan memperbesar risiko susulan."],"apd":{"wajib":"Safety helmet, safety shoes toe cap, sarung tangan.","tambahan":"Masker, kacamata keselamatan."},"darurat":{"potensi":"Bahaya sisa kembali aktif, korban baru saat pembersihan.","respon":"Hentikan pekerjaan, amankan ulang area, panggil COE.","alat":"Garis pembatas, kamera, formulir laporan, kotak P3K."},"catatan":"Batas waktu pelaporan ke instansi perlu diverifikasi dengan peraturan yang berlaku.","dasar":["UU No. 1/1970","Permenaker No. 3/1998 (pelaporan kecelakaan","perlu verifikasi)","Permenaker No. 5/2018","praktik industri","Permenaker No. 3/1998","PP No. 22/2021","perlu verifikasi","Permen LHK P.6/2021","PP No. 50/2012 (investigasi dan tindak lanjut)"]},{"id":"21","title":"Kartu Kontak Darurat dan Orientasi Darurat di Lokasi Kerja Baru","steps":[{"n":1,"do":"Sebelum mulai bekerja, menanyakan ke pemilik atau pengelola lokasi: sistem alarm, titik kumpul, jalur evakuasi, klinik terdekat, dan nomor darurat setempat","items":[{"k":"wajib","t":"**Tidak mulai pekerjaan sebelum tahu titik kumpul, jalur evakuasi, dan cara memanggil bantuan di lokasi tersebut**."},{"k":"lakukan","t":"Ikuti induksi keselamatan pemilik lokasi; catat hasilnya."}]},{"n":2,"do":"Membuat atau memperbarui kartu kontak darurat: COE, atasan langsung, QSHE, klinik atau rumah sakit terdekat, kepolisian, pemadam kebakaran, ambulans, dan pengelola lokasi","items":[{"k":"wajib","t":"**Kartu kontak dibawa setiap personel dan ditempel di kendaraan atau area kerja; diperbarui tiap pindah lokasi**."},{"k":"lakukan","t":"Uji satu nomor (panggilan uji) sebelum pekerjaan dimulai."}]},{"n":3,"do":"Memastikan alat komunikasi berfungsi dan sinyal tersedia; jika tidak ada sinyal, menyepakati jadwal lapor posisi dan jalur komunikasi cadangan","items":[{"k":"wajib","t":"**Lokasi tanpa sinyal memerlukan jadwal lapor rutin dan batas waktu eskalasi yang disepakati**."},{"k":"lakukan","t":"Lanjut Tutorial 09 untuk kondisi hilang kontak."}]},{"n":4,"do":"Menentukan rute dan waktu tempuh ke fasilitas kesehatan terdekat dan mencatatnya di kartu","items":[{"k":"lakukan","t":"Catat koordinat atau patokan lokasi dan waktu tempuh; pastikan kendaraan dan pengemudi siap."}]},{"n":5,"do":"Mengulang briefing darurat singkat kepada tim sebelum kerja dimulai: siapa memimpin, ke mana berkumpul, siapa P3K, siapa menghubungi","items":[{"k":"wajib","t":"**Setiap anggota tim dapat menyebutkan titik kumpul dan pemimpin darurat sebelum kerja dimulai**."},{"k":"lakukan","t":"Catat dalam JSEA atau briefing harian."}]}],"aturan":["Tahu titik kumpul sebelum mulai kerja.","Kartu kontak dibawa dan diuji."],"siap":["Induksi lokasi tercatat.","Kartu kontak terbaru dan diuji.","Jadwal lapor posisi bila tanpa sinyal."],"jangan":["Mengandalkan nomor darurat dari lokasi sebelumnya — hindari."],"tips":["Pekerjaan di area pelanggan tetap memakai aturan darurat pemilik lokasi sekaligus aturan perusahaan.","Foto kartu kontak sebagai cadangan di HP."],"perhatian":["Nomor darurat yang tidak pernah diuji sering salah atau tidak aktif saat dibutuhkan."],"apd":{"wajib":"Sesuai pekerjaan.","tambahan":"Tidak ada."},"darurat":{"potensi":"Tidak ada bantuan karena nomor salah atau tidak ada sinyal.","respon":"Gunakan jalur komunikasi cadangan, hubungi COE, mulai pertolongan pertama.","alat":"Kartu kontak, radio atau telepon cadangan, kotak P3K."},"catatan":"Lengkapi kartu untuk setiap lokasi kerja baru.","dasar":["UU No. 1/1970","Permenaker No. 5/2018","Praktik industri"]}];
